//! Loading helpers.
use std::fs;

pub fn load(path: &str) -> String {
    fs::read_to_string(path).unwrap_or_default()
}

pub fn exists(path: &str) -> bool {
    fs::metadata(path).is_ok()
}

fn normalize(s: &str) -> String {
    s.trim().to_string()
}

