//! Loading helpers.
use std::fs;

pub fn load(path: &str, strict: bool) -> Result<String, std::io::Error> {
    let text = fs::read_to_string(path)?;
    Ok(if strict { normalize(&text) } else { text })
}

pub fn exists(path: &str) -> bool {
    fs::metadata(path).is_ok()
}

fn normalize(s: &str) -> String {
    s.trim().to_string()
}

